def is_balanced_ignoring_whitespace(s):
    allowed = set('(){}[]')
    filtered = ''.join(c for c in s if not c.isspace())
    for c in filtered:
        if c not in allowed:
            return False
    pairs = {'(': ')', '[': ']', '{': '}'}
